32	// 维度常量
33	static constexpr int64_t INPUT_DIM_NUM = 3;     // input shape: (b_n, b_s, D)
34	static constexpr int64_t INDICES_DIM_NUM = 2;   // indices shape: (T, 2)
35	static constexpr int64_t UPDATE_DIM_NUM = 2;    // update shape: (T, D)
36	static constexpr int64_t INDICES_LAST_DIM = 2;  // indices最后一维固定为2
