40	static constexpr int64_t INPUT_DIM_BS_INDEX = 1;  // input第1维索引 (b_s)
41	static constexpr int64_t INPUT_DIM_D_INDEX = 2;   // input第2维索引 (D)
42	
43	// 内存对齐与UB布局
44	static constexpr int64_t ALIGN_BYTES = 32;
45	static constexpr int64_t RESERVED_UB_SIZE = 4 * 1024;  // 4KB预留给栈和临时变量
46	static constexpr int64_t DOUBLE_BUFFER_NUM = 2;
47	static constexpr int64_t DATA_COPY_MAX_BLOCK = 4064;
48	
49	// shape取值范围约束 (闭区间)
50	static constexpr int64_t BN_MIN = 1;
51	static constexpr int64_t BN_MAX = 2 * 1024 * 1024;       // 2M
52	static constexpr int64_t BS_MIN = 1;
53	static constexpr int64_t BS_MAX = 1024;
54	static constexpr int64_t D_MIN = 1;
55	static constexpr int64_t D_MAX = 2048;
56	static constexpr int64_t T_MIN = 1;
57	static constexpr int64_t T_MAX = 1024 * 1024;       // 1M
