103	ge::graphStatus AiInfraScatterBlockUpdateBaseTiling::GetInputShapeAndStride()
104	{
105	    // ========== 获取input (var) 信息: shape (b_n, b_s, D), 支持第0维非连续 ==========
106	    auto inputDesc = context_->GetInputDesc(INPUT_VAR_INDEX);
107	    OP_CHECK_NULL_WITH_CONTEXT(context_, inputDesc);
108	    inputDtype_ = inputDesc->GetDataType();
109	
110	    // 校验input数据类型: 仅支持FP32/BF16/FP16/INT8
111	    OP_CHECK_IF(inputDtype_ != ge::DT_FLOAT && inputDtype_ != ge::DT_BF16 &&
112	                inputDtype_ != ge::DT_FLOAT16 && inputDtype_ != ge::DT_INT8,
113	        OP_LOGE(context_->GetNodeName(), "input dtype only supports FP32/BF16/FP16/INT8"),
114	        return ge::GRAPH_FAILED);
115	
116	    // 获取input shape和stride
117	    auto inputShapePtr = context_->GetInputShape(INPUT_VAR_INDEX);
118	    OP_CHECK_NULL_WITH_CONTEXT(context_, inputShapePtr);
119	
120	    auto* inputStride = context_->GetInputStride(INPUT_VAR_INDEX);
121	    if (inputStride != nullptr && inputStride->GetDimNum() > 0) {
122	        // 非连续tensor，通过input stride判断
123	        auto viewShape = inputShapePtr->GetShape();
124	        OP_CHECK_IF(viewShape.GetDimNum() != static_cast<size_t>(INPUT_DIM_NUM),
125	            OP_LOGE(context_->GetNodeName(),
126	                    "input should be 3D (b_n, b_s, D), but got %zu dims", viewShape.GetDimNum()),
127	            return ge::GRAPH_FAILED);
128	        bn_ = viewShape.GetDim(INPUT_DIM_BN_INDEX);
129	        bs_ = viewShape.GetDim(INPUT_DIM_BS_INDEX);
130	        D_ = viewShape.GetDim(INPUT_DIM_D_INDEX);
131	        inputStride0_ = (*inputStride)[0];
132	        inputStride1_ = (*inputStride)[1];
133	    } else {
134	        // 连续tensor, 从originShape计算stride
135	        auto originShape = inputShapePtr->GetOriginShape();
136	        OP_CHECK_IF(originShape.GetDimNum() != static_cast<size_t>(INPUT_DIM_NUM),
137	            OP_LOGE(context_->GetNodeName(),
138	                    "input should be 3D (b_n, b_s, D), but got %zu dims", originShape.GetDimNum()),
139	            return ge::GRAPH_FAILED);
140	        bn_ = originShape.GetDim(INPUT_DIM_BN_INDEX);
141	        bs_ = originShape.GetDim(INPUT_DIM_BS_INDEX);
142	        D_ = originShape.GetDim(INPUT_DIM_D_INDEX);
143	        inputStride0_ = bs_ * D_;
144	        inputStride1_ = D_;
145	    }
146	    return ge::GRAPH_SUCCESS;
147	}
