278	
279	ge::graphStatus AiInfraScatterBlockUpdateBaseTiling::DoOpTiling()
280	{
281	    if (GetAndCheckInputShape() != ge::GRAPH_SUCCESS) {
282	        OP_LOGE(context_->GetNodeName(), "GetAndCheckInputShape failed!");
283	        return ge::GRAPH_FAILED;
284	    }
285	
286	    totalIndicesCount_ = T_;
287	    totalCoreNum_ = static_cast<int32_t>(aivNum_);
288	
289	    // 处理空tensor
290	    if (totalIndicesCount_ == 0) {
291	        usedCoreNum_ = 1;
292	        eachCoreIndexCount_ = 0;
293	        tailCoreIndexCount_ = 0;
294	        oneIndexSize_ = 0;
295	        oneUpdateAlignSize_ = 0;
296	        indicesPerLoad_ = 0;
297	        maxIndicesPerLoad_ = 0;
298	        return ge::GRAPH_SUCCESS;
299	    }
300	
301	    // ========== 步骤1: 计算对齐后的每行数据大小 ==========
302	    // 一行indices: 2个元素 * indicesTypeSize 字节, 用GetValue取出，不需要对齐
303	    oneIndexSize_ = INDICES_LAST_DIM * indicesTypeSize_;
304	    // 一行update: D个元素 * updateTypeSize 字节, 对齐到32字节
305	    oneUpdateAlignSize_ = AlignUp(D_ * updateTypeSize_, ALIGN_BYTES);
306	
307	    // ========== 步骤2: 分核策略 ==========
308	    // 按indices行数均分到各核
309	    eachCoreIndexCount_ = CeilDiv(totalIndicesCount_, static_cast<int64_t>(totalCoreNum_));
310	    // 实际使用的核数（可能小于totalCoreNum）
311	    usedCoreNum_ = static_cast<int32_t>(CeilDiv(totalIndicesCount_, eachCoreIndexCount_));
312	    // 最后一个核处理的行数（尾块）
313	    tailCoreIndexCount_ = totalIndicesCount_ - eachCoreIndexCount_ * (usedCoreNum_ - 1);
314	
315	    // ========== 步骤3: UB内存计算 (double buffer) ==========
316	    // 预留一部分UB空间给栈和临时变量
317	    int64_t availableUbSize = ubSize_ - RESERVED_UB_SIZE;
318	    OP_CHECK_IF(availableUbSize <= 0,
319	        OP_LOGE(context_->GetNodeName(),
320	                "UB size(%ld) too small after reserving %ld bytes", ubSize_, RESERVED_UB_SIZE),
321	        return ge::GRAPH_FAILED);
322	
323	    // double buffer: 可用UB分两半
324	    int64_t halfUbSize = availableUbSize / DOUBLE_BUFFER_NUM;
325	
326	    // 每半UB能装多少行 indices + update
327	    int64_t perLoadSize = oneIndexSize_ + oneUpdateAlignSize_;
328	    OP_CHECK_IF(perLoadSize <= 0,
329	        OP_LOGE(context_->GetNodeName(), "perLoadSize should be positive"),
330	        return ge::GRAPH_FAILED);
331	
332	    indicesPerLoad_ = halfUbSize / perLoadSize;
333	    OP_CHECK_IF(indicesPerLoad_ <= 0,
334	        OP_LOGE(context_->GetNodeName(),
335	                "UB too small for 1 row, halfUb=%ld, oneIndex=%ld, oneUpdate=%ld",
336	                halfUbSize, oneIndexSize_, oneUpdateAlignSize_),
337	        return ge::GRAPH_FAILED);
338	
339	    // ========== 步骤4: 限制最大加载行数不超过每核处理量 ==========
340	    maxIndicesPerLoad_ = std::min(eachCoreIndexCount_, indicesPerLoad_);
341	    maxIndicesPerLoad_ = std::min(maxIndicesPerLoad_, static_cast<int64_t>(DATA_COPY_MAX_BLOCK));
342	
343	    OP_LOGD(context_->GetNodeName(),
344	        "totalIndices=%ld, usedCores=%d, eachCore=%ld, tail=%ld, perLoad=%ld, "
345	        "maxPerLoad=%ld, oneIdx=%ld, oneUpd=%ld",
346	        totalIndicesCount_, usedCoreNum_, eachCoreIndexCount_,
347	        tailCoreIndexCount_, indicesPerLoad_, maxIndicesPerLoad_,
348	        oneIndexSize_, oneUpdateAlignSize_);
349	
350	    tilingKey_ = FULL_LOAD_TILING_KEY;
351	
352	    return ge::GRAPH_SUCCESS;
353	}
