/*!
 * \file test_scatter_block_update_tiling.cpp
 * \brief Tiling UT for AiInfraScatterBlockUpdate operator.
 */

#include <iostream>
#include <gtest/gtest.h>
#include "../../../op_host/ai_infra_scatter_block_update_tiling.h"
#include "tiling_context_faker.h"
#include "tiling_case_executor.h"

class ScatterBlockUpdateTiling : public testing::Test {
protected:
    static void SetUpTestCase()
    {
        std::cout << "ScatterBlockUpdateTiling SetUp" << std::endl;
    }

    static void TearDownTestCase()
    {
        std::cout << "ScatterBlockUpdateTiling TearDown" << std::endl;
    }
};

template <typename T>
static std::string TilingData2Str(void* buf, size_t size)
{
    std::string result;
    const T* data = reinterpret_cast<const T*>(buf);
    size_t len = size / sizeof(T);
    for (size_t i = 0; i < len; i++) {
        result += std::to_string(data[i]);
        result += " ";
    }
    return result;
}

// ========================== 正常用例 ==========================

/*
 * 测试用例描述：ScatterBlockUpdate算子tiling功能验证 — 连续input，网络典型值
 * 输入：
 *   - var: shape (b_n, b_s, D) = (2048, 128, 128), dtype = FP32, 连续
 *   - indices: shape (T, 2) = (16384, 2), dtype = INT32
 *   - updates: shape (T, D) = (16384, 128), dtype = FP32
 *   shape约束: b_n=[1,16K], b_s=[1,1024], D=[1,256], T=[1,256K]
 * 预期结果：tiling正常执行，返回GRAPH_SUCCESS
 */
TEST_F(ScatterBlockUpdateTiling, ScatterNdUpdateTiling_Normal_contiguous)
{
    int64_t b_n = 2048;
    int64_t b_s = 128;
    int64_t D = 128;
    int64_t T = 16384;

    optiling::AiInfraScatterBlockUpdateCompileInfo compileInfo = {};
    gert::TilingContextPara tilingContextPara("AiInfraScatterBlockUpdate",
        {
            // input 0: var, shape (b_n, b_s, D) = (2048, 128, 128), FP32, 连续
            {{{b_n, b_s, D}, {b_n, b_s, D}}, ge::DT_FLOAT, ge::FORMAT_ND},
            // input 1: indices, shape (T, 2) = (16384, 2), INT32
            {{{T, 2}, {T, 2}}, ge::DT_INT32, ge::FORMAT_ND},
            // input 2: updates, shape (T, D) = (16384, 128), FP32
            {{{T, D}, {T, D}}, ge::DT_FLOAT, ge::FORMAT_ND},
        },
        {
            // output 0: var, shape (b_n, b_s, D), FP32
            {{{b_n, b_s, D}, {b_n, b_s, D}}, ge::DT_FLOAT, ge::FORMAT_ND},
        },
        {},  // no attrs
        &compileInfo
    );

    uint64_t expectTilingKey = 1000;
    std::string expectTilingDataStr = "";
    std::vector<size_t> expectWorkspaces = {0};
    ExecuteTestCase(tilingContextPara, ge::GRAPH_SUCCESS, expectTilingKey,
                    expectTilingDataStr, expectWorkspaces, 0, TilingData2Str<int64_t>);
}

/*
 * 测试用例描述：ScatterBlockUpdate算子tiling功能验证 — 非连续input
 * 说明：当前tiling UT框架（TilingContextPara）不支持设置view/stride,
 *       InputIsView()始终返回false，因此无法覆盖非连续tensor的tiling路径。
 *       此用例使用不同的shape值验证连续路径正常工作。
 *       非连续路径的验证需要在op_api UT或ST层面完成。
 * 输入：
 *   - var: shape (b_n, b_s, D) = (512, 64, 64), dtype = BF16, 连续（框架限制）
 *   - indices: shape (T, 2) = (4096, 2), dtype = INT32
 *   - updates: shape (T, D) = (4096, 64), dtype = BF16
 * 预期结果：tiling正常执行，返回GRAPH_SUCCESS
 */
TEST_F(ScatterBlockUpdateTiling, ScatterNdUpdateTiling_Normal_incontiguous)
{
    int64_t b_n = 512;
    int64_t b_s = 64;
    int64_t D = 64;
    int64_t T = 4096;

    optiling::AiInfraScatterBlockUpdateCompileInfo compileInfo = {};
    gert::TilingContextPara tilingContextPara("AiInfraScatterBlockUpdate",
        {
            // input 0: var, shape (b_n, b_s, D) = (512, 64, 64), BF16
            {{{b_n, b_s, D}, {b_n, b_s, D}}, ge::DT_BF16, ge::FORMAT_ND},
            // input 1: indices, shape (T, 2) = (4096, 2), INT32
            {{{T, 2}, {T, 2}}, ge::DT_INT32, ge::FORMAT_ND},
            // input 2: updates, shape (T, D) = (4096, 64), BF16
            {{{T, D}, {T, D}}, ge::DT_BF16, ge::FORMAT_ND},
        },
        {
            // output 0: var, shape (b_n, b_s, D), BF16
            {{{b_n, b_s, D}, {b_n, b_s, D}}, ge::DT_BF16, ge::FORMAT_ND},
        },
        {},
        &compileInfo
    );

    uint64_t expectTilingKey = 1000;
    std::string expectTilingDataStr = "";
    std::vector<size_t> expectWorkspaces = {0};
    ExecuteTestCase(tilingContextPara, ge::GRAPH_SUCCESS, expectTilingKey,
                    expectTilingDataStr, expectWorkspaces, 0, TilingData2Str<int64_t>);
}

/*
 * 测试用例描述：ScatterBlockUpdate算子tiling功能验证 — D=1, INT64 indices
 * 输入：
 *   - var: shape (b_n, b_s, D) = (100, 50, 1), dtype = FP16
 *   - indices: shape (T, 2) = (200, 2), dtype = INT64
 *   - updates: shape (T, D) = (200, 1), dtype = FP16
