            {{{T, 2}, {T, 2}}, ge::DT_INT64, ge::FORMAT_ND},
            // input 2: updates, shape (200, 1), FP16
            {{{T, D}, {T, D}}, ge::DT_FLOAT16, ge::FORMAT_ND},
        },
        {
            // output 0: var, shape (100, 50, 1), FP16
            {{{b_n, b_s, D}, {b_n, b_s, D}}, ge::DT_FLOAT16, ge::FORMAT_ND},
