// ========================== 异常用例 ==========================

/*
 * 测试用例描述：input维度错误 — input应为3D，传入2D
 * 输入：
 *   - var: shape (b_n, b_s) = (2048, 128), dtype = FP32（缺少D维度）
 *   - indices: shape (T, 2) = (16384, 2), dtype = INT32
 *   - updates: shape (T, D) = (16384, 128), dtype = FP32
 * 预期结果：tiling失败，返回GRAPH_FAILED
 */
TEST_F(ScatterBlockUpdateTiling, ScatterNdUpdateTiling_Abnormal_wrong_input_dim)
{
    int64_t b_n = 2048;
