            // input 0: var, 2D shape (b_n, b_s) — 错误：缺少D维度
            {{{b_n, b_s}, {b_n, b_s}}, ge::DT_FLOAT, ge::FORMAT_ND},
            // input 1: indices, shape (T, 2), INT32
            {{{T, 2}, {T, 2}}, ge::DT_INT32, ge::FORMAT_ND},
            // input 2: updates, shape (T, D), FP32
            {{{T, D}, {T, D}}, ge::DT_FLOAT, ge::FORMAT_ND},
        },
        {
            {{{b_n, b_s, D}, {b_n, b_s, D}}, ge::DT_FLOAT, ge::FORMAT_ND},
