/*
 * 测试用例描述：indices维度错误 — indices应为2D，传入3D
 * 输入：
 *   - var: shape (b_n, b_s, D) = (2048, 128, 128), dtype = FP32
 *   - indices: shape (T, 2, 1) = (16384, 2, 1), dtype = INT32（错误：多了一个维度）
 *   - updates: shape (T, D) = (16384, 128), dtype = FP32
 * 预期结果：tiling失败，返回GRAPH_FAILED
 */
TEST_F(ScatterBlockUpdateTiling, ScatterNdUpdateTiling_Abnormal_wrong_indices_dim)
{
    int64_t b_n = 2048;
    int64_t b_s = 128;
