/*
 * 测试用例描述：update维度错误 — update应为2D，传入3D
 * 输入：
 *   - var: shape (b_n, b_s, D) = (2048, 128, 128), dtype = FP32
 *   - indices: shape (T, 2) = (16384, 2), dtype = INT32
 *   - updates: shape (T, D, 1) = (16384, 128, 1), dtype = FP32（错误：多了一个维度）
 * 预期结果：tiling失败，返回GRAPH_FAILED
 */
TEST_F(ScatterBlockUpdateTiling, ScatterNdUpdateTiling_Abnormal_wrong_update_dim)
{
    int64_t b_n = 2048;
