    );

    ExecuteTestCase(tilingContextPara, ge::GRAPH_FAILED, 0, "", {}, 0, TilingData2Str<int64_t>);
}

/*
 * 测试用例描述：input数据类型错误 — input仅支持FP32/BF16/FP16/INT8，传入INT32
 * 输入：
 *   - var: shape (b_n, b_s, D) = (2048, 128, 128), dtype = INT32（错误：不支持）
 *   - indices: shape (T, 2) = (16384, 2), dtype = INT32
 *   - updates: shape (T, D) = (16384, 128), dtype = INT32
 * 预期结果：tiling失败，返回GRAPH_FAILED
 */
TEST_F(ScatterBlockUpdateTiling, ScatterNdUpdateTiling_Abnormal_wrong_input_dtype)
{
    int64_t b_n = 2048;
    int64_t b_s = 128;
    int64_t D = 128;
    int64_t T = 16384;

    optiling::AiInfraScatterBlockUpdateCompileInfo compileInfo = {};
    gert::TilingContextPara tilingContextPara("AiInfraScatterBlockUpdate",
        {
            // input 0: var, dtype = INT32 — 错误：仅支持FP32/BF16/FP16/INT8
            {{{b_n, b_s, D}, {b_n, b_s, D}}, ge::DT_INT32, ge::FORMAT_ND},
            // input 1: indices, INT32
            {{{T, 2}, {T, 2}}, ge::DT_INT32, ge::FORMAT_ND},
            // input 2: updates, INT32
            {{{T, D}, {T, D}}, ge::DT_INT32, ge::FORMAT_ND},
        },
        {
            {{{b_n, b_s, D}, {b_n, b_s, D}}, ge::DT_INT32, ge::FORMAT_ND},
        },
        {},
        &compileInfo
    );

    ExecuteTestCase(tilingContextPara, ge::GRAPH_FAILED, 0, "", {}, 0, TilingData2Str<int64_t>);
}

/*
 * 测试用例描述：indices数据类型错误 — indices仅支持INT32/INT64，传入FP32
 * 输入：
 *   - var: shape (b_n, b_s, D) = (2048, 128, 128), dtype = FP32
 *   - indices: shape (T, 2) = (16384, 2), dtype = FP32（错误：仅支持INT32/INT64）
 *   - updates: shape (T, D) = (16384, 128), dtype = FP32
 * 预期结果：tiling失败，返回GRAPH_FAILED
 */
TEST_F(ScatterBlockUpdateTiling, ScatterNdUpdateTiling_Abnormal_wrong_indices_dtype)
{
    int64_t b_n = 2048;
    int64_t b_s = 128;
    int64_t D = 128;
    int64_t T = 16384;

    optiling::AiInfraScatterBlockUpdateCompileInfo compileInfo = {};
