            {{{b_n, b_s, D}, {b_n, b_s, D}}, ge::DT_FLOAT, ge::FORMAT_ND},
            // input 1: indices, dtype = FP32 — 错误：仅支持INT32/INT64
            {{{T, 2}, {T, 2}}, ge::DT_FLOAT, ge::FORMAT_ND},
