/*
 * 测试用例描述：update数据类型与input不一致
 * 输入：
 *   - var: shape (b_n, b_s, D) = (2048, 128, 128), dtype = FP32
 *   - indices: shape (T, 2) = (16384, 2), dtype = INT32
 *   - updates: shape (T, D) = (16384, 128), dtype = FP16（错误：应与input相同，为FP32）
 * 预期结果：tiling失败，返回GRAPH_FAILED
 */
TEST_F(ScatterBlockUpdateTiling, ScatterNdUpdateTiling_Abnormal_wrong_update_dtype)
{
    int64_t b_n = 2048;
    int64_t b_s = 128;
    int64_t D = 128;
