/*
 * 测试用例描述：update的D维度与input的D维度不一致
 * 输入：
 *   - var: shape (b_n, b_s, D) = (2048, 128, 128), dtype = FP32
 *   - indices: shape (T, 2) = (16384, 2), dtype = INT32
 *   - updates: shape (T, D') = (16384, 64), dtype = FP32（错误：D'=64 != D=128）
 * 预期结果：tiling失败，返回GRAPH_FAILED
 */
TEST_F(ScatterBlockUpdateTiling, ScatterNdUpdateTiling_Abnormal_different_D)
{
    int64_t b_n = 2048;
    int64_t b_s = 128;
    int64_t D = 128;
    int64_t D_wrong = 64;
    int64_t T = 16384;

    optiling::AiInfraScatterBlockUpdateCompileInfo compileInfo = {};
    gert::TilingContextPara tilingContextPara("AiInfraScatterBlockUpdate",
        {
            // input 0: var, shape (b_n, b_s, D) = (2048, 128, 128), FP32
            {{{b_n, b_s, D}, {b_n, b_s, D}}, ge::DT_FLOAT, ge::FORMAT_ND},
            // input 1: indices, shape (T, 2), INT32
            {{{T, 2}, {T, 2}}, ge::DT_INT32, ge::FORMAT_ND},
            // input 2: updates, shape (T, D') = (16384, 64) — 错误：D'!=D
            {{{T, D_wrong}, {T, D_wrong}}, ge::DT_FLOAT, ge::FORMAT_ND},
        },
        {
            {{{b_n, b_s, D}, {b_n, b_s, D}}, ge::DT_FLOAT, ge::FORMAT_ND},
        },
        {},
        &compileInfo
    );

    ExecuteTestCase(tilingContextPara, ge::GRAPH_FAILED, 0, "", {}, 0, TilingData2Str<int64_t>);
