/*
 * 测试用例描述：b_s超出范围 — b_s=[1,1024]，传入2000
 * 输入：
 *   - var: shape (b_n, b_s, D) = (2048, 2000, 128), dtype = FP32（错误：b_s=2000 > 1024）
 *   - indices: shape (T, 2) = (16384, 2), dtype = INT32
 *   - updates: shape (T, D) = (16384, 128), dtype = FP32
 * 预期结果：tiling失败，返回GRAPH_FAILED
 */
TEST_F(ScatterBlockUpdateTiling, ScatterNdUpdateTiling_Abnormal_exceed_bs)
{
    int64_t b_n = 2048;
    int64_t b_s = 2000;  // 超出范围 [1, 1024]
