import pytest
import torch
import torch_npu
import omni_custom_ops
from torch_npu.testing.testcase import TestCase, run_tests


def golden_scatter_block_update(input_tensor, indices, updates):
    """CPU单标杆: input[indices[k,0], indices[k,1], :] = updates[k, :]"""
    output = input_tensor.clone()
    for k in range(indices.shape[0]):
        idx0 = indices[k, 0].item()
        idx1 = indices[k, 1].item()
        output[idx0, idx1, :] = updates[k, :]
    return output


def make_noncontig_dim0(tensor, pad=128):
    """构造第0维非连续的tensor (通过as_strided, dim0 stride增加pad个元素)"""
    b_n, b_s, D = tensor.shape
    stride_0 = b_s * D + pad
    base = torch.zeros(b_n, stride_0, dtype=tensor.dtype, device=tensor.device)
    view = torch.as_strided(base, size=(b_n, b_s, D), stride=(stride_0, D, 1))
    view.copy_(tensor)
    return view


def run_scatter_block_update(b_n, b_s, D, T, dtype, indices_dtype=torch.int32,
                             noncontig=False, pad=128):
    """执行一次scatter_block_update并与CPU标杆做二进制一致比较"""
    torch.manual_seed(42)

    # 构造input
    if dtype == torch.int8:
        input_cpu = torch.randint(-128, 127, (b_n, b_s, D), dtype=dtype)
    else:
        input_cpu = torch.randn(b_n, b_s, D, dtype=dtype)

    # 构造indices: (T, 2), 范围 [0, b_n) x [0, b_s)
    flat_indices = torch.randperm(b_n * b_s)[:T]
    idx0 = (flat_indices // b_s).to(indices_dtype)
    idx1 = (flat_indices % b_s).to(indices_dtype)
    indices = torch.stack([idx0, idx1], dim=1)

    # 构造updates: (T, D)
    if dtype == torch.int8:
        updates = torch.randint(-128, 127, (T, D), dtype=dtype)
    else:
        updates = torch.randn(T, D, dtype=dtype)

    # CPU golden
    golden_output = golden_scatter_block_update(input_cpu, indices, updates)

    # NPU执行 (原地版本)
    input_npu = input_cpu.npu()
    if noncontig:
        input_npu = make_noncontig_dim0(input_npu, pad=pad)
    else:
        input_npu = input_npu.clone()
    indices_npu = indices.npu()
    updates_npu = updates.npu()

    torch.ops.custom.npu_ai_infra_scatter_block_update_(input_npu, indices_npu, updates_npu)

    # 二进制一致比较
    npu_output = input_npu.cpu()
    if not torch.equal(golden_output, npu_output):
        max_diff = (golden_output.float() - npu_output.float()).abs().max().item()
        mismatch = (golden_output != npu_output).sum().item()
        total = golden_output.numel()
        pytest.fail(
            f"Binary mismatch! shape=({b_n},{b_s},{D}), T={T}, dtype={dtype}, "
            f"noncontig={noncontig}, max_diff={max_diff}, "
            f"mismatch_elements={mismatch}/{total}"
        )


